function S({registerIndicator:g,sourceValues:L,nulls:r}){g({id:"oa-pmo",name:"Price Momentum Oscillator (PMO)",category:"Momentum",placement:"pane",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"rocLength",type:"number",label:"ROC Length",default:35,min:1,max:5e3,step:1},{key:"smooth1",type:"number",label:"First Smoothing Length",default:20,min:1,max:5e3,step:1},{key:"smooth2",type:"number",label:"Second Smoothing Length",default:10,min:1,max:5e3,step:1},{key:"signalLength",type:"number",label:"Signal Line Length",default:10,min:1,max:5e3,step:1}],plots:[{key:"pmo",type:"line",title:"PMO",style:{color:"#2962ff",lineWidth:2}},{key:"signal",type:"line",title:"Signal",style:{color:"#ef5350",lineWidth:2}}],calc(c,t){const M=Math.max(1,Math.floor(Number(t.rocLength)||35)),d=Math.max(1,Math.floor(Number(t.smooth1)||20)),x=Math.max(1,Math.floor(Number(t.smooth2)||10)),F=Math.max(1,Math.floor(Number(t.signalLength)||10)),u=L(c,t.source??"close"),s=c.length,h=new Array(s).fill(NaN),N=new Array(s).fill(NaN),f=2/(d+1),p=2/(x+1),b=2/(F+1);let o=NaN,i=NaN,n=NaN;for(let e=0;e<s;e++){const k=Math.min(M,e),y=u[e],l=u[e-k];let a=NaN;Number.isFinite(y)&&Number.isFinite(l)&&l!==0&&(a=100*(y-l)/l,Number.isFinite(a)||(a=NaN)),o=Number.isFinite(o)?o*(1-f)+a*f:a,i=Number.isFinite(i)?i*(1-p)+o*p:o;const m=i;n=Number.isFinite(n)?n*(1-b)+m*b:m,Number.isFinite(m)&&(h[e]=m),Number.isFinite(n)&&(N[e]=n)}return{pmo:r(h),signal:r(N)}}})}export{S as default};
